package org.agentfrc.lesson;
import static org.junit.jupiter.api.Assertions.*;
import org.junit.jupiter.api.*;
class PregripSupervisorTest {
 static PregripSupervisor.Observation o(int k,boolean closed,double travel,double load,boolean exit){return new PregripSupervisor.Observation(k,k*.02,true,true,closed,travel,travel,load,load,0,0,exit);}
 @Test void freshBaselineDwellGateFeedbackThenFeed(){var p=new PregripSupervisor();p.update(0,o(0,true,60,0,false));for(int k=1;k<=6;k++){var r=p.update(k*.02,o(k,true,0,15,false));assertFalse(r.openGate());assertEquals(0,r.feedDuty());}var r=p.update(.14,o(7,true,0,15,false));assertTrue(r.openGate());assertEquals(0,r.feedDuty());r=p.update(.16,o(8,false,0,15,false));assertEquals(PregripSupervisor.State.FEED,r.state());assertEquals(.08,r.feedDuty());assertEquals(PregripSupervisor.State.DONE,p.update(.18,o(9,false,0,0,true)).state());}
 @Test void preloadedBaselineAndStuckHighCannotArm(){var p=new PregripSupervisor();assertEquals(PregripSupervisor.State.FAULT,p.update(0,o(0,true,0,15,false)).state());p=new PregripSupervisor();assertEquals(PregripSupervisor.State.FAULT,p.update(0,o(0,true,60,15,false)).state());}
 @Test void noContactOrUnilateralContactCannotRelease(){var p=new PregripSupervisor();p.update(0,o(0,true,60,0,false));for(int k=1;k<=26;k++){var obs=new PregripSupervisor.Observation(k,k*.02,true,true,true,0,0,15,0,0,0,false);var r=p.update(k*.02,obs);assertFalse(r.openGate());assertEquals(0,r.feedDuty());}assertEquals(PregripSupervisor.State.FAULT,p.update(.54,o(27,true,0,0,false)).state());}
 @Test void staleMissingNonfiniteOrReplayFaults(){for(int mode=0;mode<4;mode++){var p=new PregripSupervisor();p.update(0,o(0,true,60,0,false));var obs=mode==0?null:mode==1?o(0,true,60,0,false):mode==2?o(2,true,0,15,false):new PregripSupervisor.Observation(1,.02,true,true,true,0,0,Double.NaN,15,0,0,false);assertEquals(PregripSupervisor.State.FAULT,p.update(mode==2?.04:.02,obs).state());}}
 @Test void lostGripAfterOpenDoesNotCommandGateSlam(){var p=new PregripSupervisor();p.update(0,o(0,true,60,0,false));for(int k=1;k<=8;k++)p.update(k*.02,o(k,k<8,0,15,false));var r=p.update(.18,o(9,false,0,0,false));assertEquals(PregripSupervisor.State.FAULT,r.state());assertFalse(r.motionEnabled());assertTrue(r.openGate());assertEquals(0,r.feedDuty());}
 @Test void coordinatedForgedReadbacksStillAuthorizeLogicalFeed(){boolean physicalContact=false;assertFalse(physicalContact);var p=new PregripSupervisor();p.update(0,o(0,true,60,0,false));for(int k=1;k<=8;k++)p.update(k*.02,o(k,k<8,0,15,false));assertEquals(PregripSupervisor.State.FEED,p.update(.18,o(9,false,0,15,false)).state());/* Virtual consistency is not independent physical truth. */}
 @Test void missingGateOpeningFeedbackNeverFeeds(){var p=new PregripSupervisor();p.update(0,o(0,true,60,0,false));PregripSupervisor.Output r=null;for(int k=1;k<=20;k++){r=p.update(k*.02,o(k,true,0,15,false));assertEquals(0,r.feedDuty());}assertEquals(PregripSupervisor.State.FAULT,r.state());}
 @Test void missedUpdatesOnlyFaultOnReturn(){var p=new PregripSupervisor();p.update(0,o(0,true,60,0,false));PregripSupervisor.Output last=null;for(int k=1;k<=8;k++)last=p.update(k*.02,o(k,k<8,0,15,false));assertEquals(.08,last.feedDuty());/* No independent tick exists in this class; last output persists until another call. */assertEquals(PregripSupervisor.State.FAULT,p.update(.30,o(15,false,0,15,false)).state());}
 @AfterAll static void binding() throws Exception {
  String token=System.getenv("FRC_PREGRIP_RUN_ID"),output=System.getenv("FRC_PREGRIP_RUNTIME");if(token==null&&output==null)return;assertNotNull(token);assertNotNull(output);var p=new java.util.Properties();p.setProperty("runId",token);
  for(Class<?> c:new Class<?>[]{PregripSupervisor.class,PregripSupervisor.State.class,PregripSupervisor.Observation.class,PregripSupervisor.Output.class,PregripSupervisorTest.class}){String n=c.getName().substring(c.getName().lastIndexOf('.')+1);p.setProperty(n+"Sha256",java.util.HexFormat.of().formatHex(java.security.MessageDigest.getInstance("SHA-256").digest(c.getResourceAsStream(n+".class").readAllBytes())));}
  try(var stream=java.nio.file.Files.newOutputStream(java.nio.file.Path.of(output),java.nio.file.StandardOpenOption.CREATE_NEW)){p.store(stream,"Fresh virtual pregrip protocol");}System.out.println("PREGRIP_RUN_ID="+token);
 }
}
